const kanbanCounts = atom({})

const SOURCE_LABEL = {
  kanban: '⚙ Kanban',
  tool: '⚙ Subagent',
  cron: '⏱ Routine',
  oneshot: '✉ Pesan',
  delegate: '⚙ Subagent'
